from django.http import HttpResponse

def faremah_home(request):
    submitted = request.method == "POST"
    status = "<div class='ok'>درخواست شما دریافت شد؛ برای هماهنگی با فره‌ماه تماس می‌گیریم.</div>" if submitted else ""
    html = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>فره‌ماه | مرکز لیزر و زیبایی در شیراز</title><meta name="description" content="فره‌ماه؛ مرکز لیزر و زیبایی در شیراز با مشاوره شفاف و برنامه اختصاصی."><style>:root{--i:#211a2e;--m:#786f83;--g:#c9a56a;--c:#fffaf7;--r:#f7edf1}*{box-sizing:border-box}body{margin:0;background:var(--c);color:var(--i);font-family:Tahoma,Arial;line-height:1.9}.w{max-width:1100px;margin:auto;padding:0 22px}nav{display:flex;justify-content:space-between;align-items:center;padding:24px 0}.brand{font-size:1.4rem;font-weight:bold}.brand small{display:block;color:var(--m);font-size:.7rem;font-weight:normal}.btn{display:inline-block;background:var(--i);color:#fff;padding:11px 21px;border-radius:30px;border:0;font:inherit;text-decoration:none;cursor:pointer}.gold{background:var(--g);color:var(--i)}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center;padding:70px 0 90px}.ey{color:#9a6f78;font-weight:bold}.hero h1{font-size:clamp(2.6rem,6vw,5rem);line-height:1.25;margin:12px 0}.muted{color:var(--m);font-size:1.1rem}.visual{height:430px;border-radius:42px;background:linear-gradient(145deg,#ead3d9,#cbb8ca 55%,#7a657e);box-shadow:0 24px 60px #8c697d33;position:relative;overflow:hidden}.visual:after{content:"";position:absolute;width:290px;height:430px;border-radius:50% 50% 42% 42%;background:linear-gradient(120deg,#fff9,#e4c1bf,#6c506b);bottom:-140px;left:25%;transform:rotate(9deg)}section{padding:70px 0;border-top:1px solid #eadfe4}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:28px}.card,.panel{background:#fff;border:1px solid #eadfe4;border-radius:24px;padding:25px}.num{color:var(--g);font-size:1.4rem;font-weight:bold}.split{display:grid;grid-template-columns:1fr 1fr;gap:26px}.panel{background:var(--r)}form{display:grid;gap:11px}input,textarea{width:100%;padding:13px;border:1px solid #eadfe4;border-radius:13px;font:inherit}textarea{min-height:95px}.ok{background:#e6f4eb;border-radius:12px;padding:12px;margin-bottom:12px}@media(max-width:740px){.hero,.split{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.hero{padding:30px 0 50px}.visual{height:300px}}</style></head><body><div class="w"><nav><a class="brand" href="/faremah/">فره‌ماه<small>زیبایی در مدار شکوه · زیرمجموعه زمرد ملل</small></a><a class="btn gold" href="#contact">درخواست مشاوره</a></nav><main><section class="hero"><div><div class="ey">مرکز لیزر و زیبایی · شیراز</div><h1>مراقبت حرفه‌ای،<br>با حس خوبِ خودت.</h1><p class="muted">فره‌ماه برای کسانی است که نتیجه شفاف، مشاوره محترمانه و برنامه‌ای متناسب با شرایط خود می‌خواهند.</p><a class="btn" href="#services">آشنایی با خدمات</a></div><div class="visual"></div></section><section id="services"><div class="ey">خدمات منتخب</div><h2>هر تصمیم، با ارزیابی درست شروع می‌شود.</h2><div class="cards"><article class="card"><div class="num">۰۱</div><h3>لیزر موهای زائد</h3><p class="muted">برنامه‌ریزی جلسه‌ها و توضیح مراقبت‌های قبل و بعد.</p></article><article class="card"><div class="num">۰۲</div><h3>مراقبت پوست</h3><p class="muted">انتخاب مسیر مراقبت متناسب با نوع پوست و هدف شما.</p></article><article class="card"><div class="num">۰۳</div><h3>مشاوره اختصاصی</h3><p class="muted">پاسخ روشن و تعیین قدم بعدی بدون فشار برای تصمیم عجولانه.</p></article></div></section><section id="contact"><div class="split"><div><div class="ey">مشاوره و هماهنگی</div><h2>برای شروع، چند خط برای ما بنویسید.</h2><p class="muted">نام و شماره تماس را وارد کنید تا برای هماهنگی با شما تماس بگیریم.</p></div><div class="panel">""" + status + """<form method="post"><input name="name" placeholder="نام و نام خانوادگی" required><input name="phone" placeholder="شماره تماس" required><textarea name="message" placeholder="توضیحات"></textarea><button class="btn gold" type="submit">ثبت درخواست مشاوره</button></form></div></div></section></main><footer style="padding:30px 0;color:var(--m)">© فره‌ماه · زیرمجموعه شرکت کشت و صنعت زمرد ملل · شیراز</footer></div></body></html>"""
    return HttpResponse(html)
